function validate([nums1, nums2, diff]) {
  if (!Array.isArray(nums1) || !Array.isArray(nums2)) return 'nums1 and nums2 must be arrays.';
  if (nums1.length !== nums2.length) return 'nums1 and nums2 need the same length.';
  if (nums1.length < 2 || nums1.length > 100000) return 'The arrays need 2 to 100000 values.';
  const bad = v => !Number.isInteger(v) || v < -10000 || v > 10000;
  if (nums1.some(bad) || nums2.some(bad)) return 'Each value is an integer from -10000 to 10000.';
  if (!Number.isInteger(diff) || diff < -10000 || diff > 10000) return 'diff is an integer from -10000 to 10000.';
  return null;
}

