function numberOfPairs(nums1, nums2, diff) {
  const OFFSET = 20001;
  const size = 40001;
  const tree = new Array(size + 1).fill(0);
  let pairs = 0;

  for (let j = 0; j < nums1.length; j++) {
    const value = nums1[j] - nums2[j];
    let index = Math.min(size, value + diff + OFFSET);
    while (index > 0) {
      pairs += tree[index];
      index -= index & -index;
    }
    index = value + OFFSET;
    while (index <= size) {
      tree[index]++;
      index += index & -index;
    }
  }
  return pairs;
}

